/* config.h for the Nintendo 3DS port of Aleph One (devkitARM + libctru).
 *
 * HAND-MAINTAINED. This file is not generated by configure: the 3DS build
 * (ports/3ds/CMakeLists.txt) has no autoconf step. It plays the role of the
 * config.h that
 *
 *     ./configure --disable-opengl --disable-network --enable-std-filesystem
 *
 * produced for the stage 2 Linux build with std::filesystem (docker volume
 * aleph-host-build-fsstd), adapted for devkitARM r68 / newlib 4.6.0 /
 * libctru 2.7.0. Every engine translation unit sees it through
 * -DHAVE_CONFIG_H, exactly as with automake.
 *
 * How each value was decided (checks run 2026-10-10 against
 * $DEVKITARM/arm-none-eabi/include and by linking with
 * -specs=3dsx.specs -lctru -lm, the same tests autoconf runs):
 *   - feature switches follow the minimal 3DS feature set: no network,
 *     no OpenGL, std::filesystem, no optional libraries;
 *   - HAVE_<header>_H: defined when "#include <header>" compiles
 *     (AC_CHECK_HEADERS / AC_INCLUDES_DEFAULT);
 *   - HAVE_<func>: defined when an autoconf-style link test of the symbol
 *     succeeds; notes say what the newlib implementation does.
 * Keep it in sync with configure.ac when upstream adds new checks.
 */

#ifndef A1_3DS_CONFIG_H
#define A1_3DS_CONFIG_H

#if !defined(__3DS__) || !defined(A1_PLATFORM_3DS)
#error "ports/3ds/config.h is only for the 3DS build (expects __3DS__ and A1_PLATFORM_3DS)"
#endif

/* ---------------------------------------------------------------------- */
/* Feature selection (configure.ac AX_ARG_ENABLE / AX_ARG_WITH results)    */

/* Use std::filesystem instead of Boost::Filesystem. Verified to compile,
   link and run (Azahar emulator) with devkitARM's libstdc++, see
   docs/3ds/ENVIRONMENT.md "std::filesystem". */
#define A1_FS_STD 1

/* Build without network play (--disable-network). */
#define A1_NO_NETWORK 1

/* Use the standalone hub: no (network is off). */
/* #undef A1_NETWORK_STANDALONE_HUB */

/* Film export needs vpx/matroska/ebml/vorbis/vorbisenc/libyuv: off. */
/* #undef FILM_EXPORT */

/* define if the Boost library is available (headers only; installed by
   scripts/3ds/install-boost-headers.sh into $DEVKITPRO/portlibs/3ds) */
#define HAVE_BOOST /**/

/* Boost::Filesystem is not used (A1_FS_STD). */
/* #undef HAVE_BOOST_FILESYSTEM */

/* define if the compiler supports basic C++17 syntax (-std=gnu++17) */
#define HAVE_CXX17 1

/* Required packages (AX_REQUIRE_PKG). */
#define HAVE_SDL 1
#define HAVE_SDL_TTF 1
#define HAVE_ZLIB 1

/* OpenAL Soft 1.25.2 (scripts/3ds/build-openal.sh) */
#define HAVE_OPENAL 1

/* libsndfile 1.2.2 without external codecs (scripts/3ds/build-libsndfile.sh) */
#define HAVE_SNDFILE 1

/* Optional features, all off for the minimal 3DS build. */
/* #undef HAVE_OPENGL */          /* --disable-opengl */
/* #undef HAVE_GL_GLEXT_H */
/* #undef HAVE_SDL_IMAGE */       /* no SDL2_image for the 3DS */
/* #undef HAVE_CURL */            /* network-only */
/* #undef HAVE_ZZIP */            /* no zziplib */
/* #undef HAVE_PNG */             /* PNG screenshots off; libpng is linked only
                                     because freetype needs it */
/* #undef HAVE_MINIUPNPC */       /* network-only */
/* #undef HAVE_LIBMINIUPNPC */
/* #undef HAVE_MINIUPNPC_MINIUPNPC_H */
/* #undef HAVE_CATCH2 */          /* tests are not built */
/* #undef HAVE_STEAM */
/* #undef HAVE_NFD */             /* no native file dialogs */
/* #undef HAVE_LIBNFD */
/* #undef HAVE_NFD_H */
/* #undef HAVE_VPX */             /* film export libraries: none */
/* #undef HAVE_MATROSKA */
/* #undef HAVE_EBML */
/* #undef HAVE_VORBIS */
/* #undef HAVE_VORBISENC */
/* #undef HAVE_LIBYUV */
/* #undef HAVE_LIBYUV_CONVERT_H */
/* #undef WIN32_DISABLE_MUSIC */  /* Windows-only */

/* ---------------------------------------------------------------------- */
/* Headers (newlib, $DEVKITARM/arm-none-eabi/include): all compile.        */

#define HAVE_INTTYPES_H 1
#define HAVE_STDINT_H 1
#define HAVE_STDIO_H 1
#define HAVE_STDLIB_H 1
#define HAVE_STRINGS_H 1
#define HAVE_STRING_H 1
#define HAVE_SYS_STAT_H 1
#define HAVE_SYS_TYPES_H 1
#define STDC_HEADERS 1

/* unistd.h compiles; access(), close(), isatty() etc. link (newlib +
   libsysbase devoptab). Used by shell.cpp, preferences.cpp, FileHandler.cpp. */
#define HAVE_UNISTD_H 1

/* pwd.h exists in newlib, but getpwuid()/getuid()/getlogin() do NOT link
   (undefined references with -specs=3dsx.specs -lctru). autoconf only tests
   that the header compiles and would define this; it is left undefined
   because nothing behind it works. Its only user (Misc/Logging.cpp, an
   include only) also guards it with __unix__, which arm-none-eabi-gcc does
   not define. (The getlogin() call in Misc/preferences.cpp is behind
   `unix`, also undefined here.) */
/* #undef HAVE_PWD_H */

/* ---------------------------------------------------------------------- */
/* Functions (link test with -specs=3dsx.specs -lctru -lm).                */

/* Required by configure.ac; newlib provides both. */
#define HAVE_SNPRINTF 1
#define HAVE_VSNPRINTF 1

/* sysconf() links (newlib libc_a-sysconf.o) but only answers _SC_PAGESIZE;
   _SC_NPROCESSORS_ONLN returns -1/EINVAL. Its only user,
   Videos/Movie.cpp:get_cpu_count(), is film-export code and clamps a
   non-positive count to 1. Defined, as autoconf would. */
#define HAVE_SYSCONF 1

/* sysctlbyname(): no <sys/sysctl.h>, does not link. */
/* #undef HAVE_SYSCTLBYNAME */

/* mkstemp() links (newlib libc_a-mktemp.o, built on open() through the
   devoptab). Lua's os.tmpname() uses it with a "/tmp/lua_XXXXXX" template,
   which has no backing directory on the SD card, so os.tmpname() fails
   cleanly at run time either way (tmpnam() is the fallback). Defined, as
   autoconf would. */
#define LUA_USE_MKSTEMP 1

/* ---------------------------------------------------------------------- */
/* Package identification (AC_INIT). The version is A1_DATE_VERSION from
   Source_Files/Misc/alephversion.h; ports/3ds/CMakeLists.txt warns at
   configure time if the two drift apart. */

#define PACKAGE "AlephOne"
#define PACKAGE_BUGREPORT "https://github.com/Aleph-One-Marathon/alephone/issues"
#define PACKAGE_NAME "Aleph One"
#define PACKAGE_STRING "Aleph One 20250930"
#define PACKAGE_TARNAME "AlephOne"
#define PACKAGE_URL "https://alephone.lhowon.org/"
#define PACKAGE_VERSION "20250930"
#define VERSION "20250930"

/* Target platform name ("$target_os $target_cpu" under autoconf). */
#define TARGET_PLATFORM "3ds arm"

#endif /* A1_3DS_CONFIG_H */
